import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Wie rechnet der Adapter?","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/05.hintergrund/01.berechnung.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/hintergrund/berechnung.md","filePath":"de/adapter/sourceanalytix/hintergrund/berechnung.md","lastUpdated":null}'),i={name:"de/adapter/sourceanalytix/hintergrund/berechnung.md"};function d(s,e,h,u,l,c){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="wie-rechnet-der-adapter" tabindex="-1">Wie rechnet der Adapter? <a class="header-anchor" href="#wie-rechnet-der-adapter" aria-label="Permalink to &quot;Wie rechnet der Adapter?&quot;">​</a></h1><p><a id="sourceanalytix-still-maintained"></a></p><h2 id="wird-sourceanalytix-noch-weiterentwickelt" tabindex="-1">Wird SourceAnalytix noch weiterentwickelt? <a class="header-anchor" href="#wird-sourceanalytix-noch-weiterentwickelt" aria-label="Permalink to &quot;Wird SourceAnalytix noch weiterentwickelt?&quot;">​</a></h2><p>Ja. Es erscheinen regelmäßig neue Versionen, derzeit im Repository „latest“. In „stable“ kommt SourceAnalytix nach einer Testphase.</p><p>Bei Fragen und Fehlern:</p><ol><li>Schau zuerst in den Tab „Probleme“ der Instanz-Einstellungen. Er prüft alle Quellen und schlägt eine Lösung vor.</li><li>Lies die Seiten zur <a href="./../fehlerbehebung/">Fehlerbehebung</a>.</li><li>Melde einen Fehler oder Wunsch als Issue im <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues" target="_blank" rel="noreferrer">GitHub-Repository</a>, mit den Versionen von SourceAnalytix, js-controller und Node.js und dem Log der Quelle.</li></ol><p><a id="values-differ-meter-portal-evcc"></a></p><h2 id="warum-weichen-die-werte-von-zahler-portal-oder-evcc-ab" tabindex="-1">Warum weichen die Werte von Zähler, Portal oder evcc ab? <a class="header-anchor" href="#warum-weichen-die-werte-von-zahler-portal-oder-evcc-ab" aria-label="Permalink to &quot;Warum weichen die Werte von Zähler, Portal oder evcc ab?&quot;">​</a></h2><p>Meist aus einem von vier Gründen: Die Quelle ist eine selten sendende Leistung, das Portal ordnet Verbrauch einem anderen Zeitpunkt zu, das Gerät misst anders als dein Zähler, oder Startwerte und Einheit passen nicht.</p><table tabindex="0"><thead><tr><th>Ursache</th><th>Erkennungszeichen</th><th>Was hilft</th></tr></thead><tbody><tr><td>Leistung (W), die nur alle paar Minuten sendet</td><td>starke Abweichung</td><td>Gesamtzähler in kWh nehmen oder öfter senden lassen</td></tr><tr><td>Pause einer Leistungsquelle</td><td>nach einem Ausfall fehlt Verbrauch oder ist zu hoch</td><td>„Maximale Lücke zwischen Leistungswerten (Minuten)“</td></tr><tr><td>anderer Zeitpunkt der Zuordnung</td><td>Tage weichen ab, die Summe über Tage stimmt</td><td>nichts, beide stimmen</td></tr><tr><td>Gerät misst anders, etwa ein Shelly 3EM je Phase</td><td>passt nicht zum Zähler im Keller</td><td>Zähler selbst auslesen, etwa mit Lesekopf</td></tr><tr><td>Startwerte, Einheit oder Gesamtstand falsch</td><td>negativ, zu hoch oder versetzt</td><td><a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a></td></tr></tbody></table><p>SourceAnalytix bucht Verbrauch auf den Tag, an dem er gemessen wurde. Eine Wallbox oder evcc bucht einen Ladevorgang oft komplett auf den Tag, an dem er endet. Über Tage gleicht sich das aus.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler oder Leistung?</a></p><p><a id="sourceanalytix-convert-watts-kwh"></a></p><h2 id="wie-rechnet-sourceanalytix-watt-in-kwh-um" tabindex="-1">Wie rechnet SourceAnalytix Watt in kWh um? <a class="header-anchor" href="#wie-rechnet-sourceanalytix-watt-in-kwh-um" aria-label="Permalink to &quot;Wie rechnet SourceAnalytix Watt in kWh um?&quot;">​</a></h2><p>Mit jedem neuen Wert: vorige Leistung mal Zeit seit dem vorigen Wert. Mit „Mittelwert bei Leistung“ nimmt SourceAnalytix das Mittel aus vorigem und neuem Wert. Die Energie wird zum Gesamtstand addiert.</p><table tabindex="0"><thead><tr><th>Zeit</th><th>Wert</th><th>ohne Mittelwert</th><th>mit Mittelwert</th></tr></thead><tbody><tr><td>10:00</td><td>0 W</td><td>Ausgangspunkt</td><td>Ausgangspunkt</td></tr><tr><td>10:30</td><td>1.000 W</td><td>0 Wh</td><td>250 Wh</td></tr><tr><td>11:00</td><td>1.000 W</td><td>500 Wh</td><td>500 Wh</td></tr><tr><td>Summe</td><td></td><td>0,5 kWh</td><td>0,75 kWh</td></tr></tbody></table><p>Ohne Mittelwert passt es zu Geräten, die abrupt schalten und nur bei Änderung senden, mit Mittelwert zu Sensoren, die regelmäßig senden. Gerechnet wird bei jedem geschriebenen Wert, auch wenn er gleich bleibt; der letzte Wert gilt bis zum nächsten.</p><p>Pausen:</p><ul><li>Der erste Wert nach Aktivierung oder Neustart ist nur der Ausgangspunkt.</li><li>Kommt lange kein Wert, wird der letzte hochgerechnet, außer „Maximale Lücke zwischen Leistungswerten (Minuten)“ ist gesetzt.</li><li>Um Mitternacht wird die Energie bis 0:00 Uhr dem alten Tag zugebucht.</li></ul><p>Bezahlt wird jeder Abschnitt mit dem Preis, der zum Zeitpunkt des Werts galt.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#sourceanalytix-compute-consumption-meter-reading">Kann SourceAnalytix aus Leistung Verbrauch berechnen?</a></p><p><a id="consumption-calculated-currentyear-lower-than"></a></p><h2 id="wie-wird-der-verbrauch-berechnet-–-und-warum-ist-currentyear-niedriger-als-mein-zahlerstand" tabindex="-1">Wie wird der Verbrauch berechnet – und warum ist currentYear niedriger als mein Zählerstand? <a class="header-anchor" href="#wie-wird-der-verbrauch-berechnet-–-und-warum-ist-currentyear-niedriger-als-mein-zahlerstand" aria-label="Permalink to &quot;Wie wird der Verbrauch berechnet – und warum ist currentYear niedriger als mein Zählerstand?&quot;">​</a></h2><p>Weil <code>currentYear.consumed.05_currentYear</code> der Verbrauch dieses Jahres ist, nicht der Zählerstand. Er ist Gesamtstand minus Startwert „Jahr“. Den Zählerstand findest du in <code>cumulativeReading</code>.</p><table tabindex="0"><thead><tr><th></th><th>Wert</th></tr></thead><tbody><tr><td>Gesamtstand</td><td>12.480 kWh</td></tr><tr><td>Startwert „Jahr“ (Stand am 1. Januar)</td><td>11.900 kWh</td></tr><tr><td><code>05_currentYear</code></td><td>580 kWh</td></tr></tbody></table><p>Die Startwerte setzt SourceAnalytix bei jedem Periodenwechsel selbst. Hast du im Laufe des Jahres aktiviert, zählt das Jahr ab diesem Tag, außer du trägst den Stand vom 1. Januar als <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwert</a> ein.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Meter-Readings</a></p>',27)])])}const g=t(i,[["render",d]]);export{m as __pageData,g as default};
